readBigbasketPage:
"use strict";
async function readBigbasketPage(query, pincode, waitMs = 12000) {
    const started = Date.now();
    const end = started + waitMs;
    while (true) {
        const text = document.body?.innerText ?? '';
        if (/access denied|captcha|verify you are human|request blocked/i.test(text))
            return { kind: 'blocked', message: 'BigBasket needs verification. Open Delivery area and try again.' };
        const chooseArea = [...document.querySelectorAll('button')].some(b => /select location/i.test(b.textContent ?? ''));
        if (chooseArea && Date.now() >= Math.min(end, started + 1500))
            return { kind: 'needs_location', message: 'Choose your delivery area in BigBasket, then search again.' };
        const selectedPin = document.querySelector('header')?.textContent?.match(/\b\d{6}\b/)?.[0];
        if (selectedPin && selectedPin !== pincode)
            return { kind: 'needs_location', message: `Choose ${pincode} in BigBasket before comparing prices.` };
        const products = [];
        for (const heading of chooseArea ? [] : document.querySelectorAll('h3')) {
            const link = heading.querySelector('a[href*="/pd/"]');
            if (!link)
                continue;
            let card = heading.parentElement;
            // The compact and desktop cards use different wrappers. Stop before another product.
            while (card && !/₹\s*[\d,]+/.test(card.innerText)) {
                const parent = card.parentElement;
                if (!parent || parent.querySelectorAll('h3').length !== 1) {
                    card = null;
                    break;
                }
                card = parent;
            }
            if (!card || card.querySelectorAll('h3').length !== 1)
                continue;
            const cardText = card.innerText;
            const eta = cardText.match(/\b(\d+)\s*mins?\b/i);
            if (!eta || +eta[1] > 60 || /tomorrow|\d+\s*(?:hours?|days?)/i.test(cardText))
                continue;
            const title = link.textContent?.trim();
            const url = new URL(link.getAttribute('href'), 'https://www.bigbasket.com');
            const id = url.pathname.match(/^\/pd\/(\d+)\//)?.[1];
            const prices = [...cardText.matchAll(/₹\s*([\d,]+(?:\.\d+)?)/g)].map(m => +m[1].replace(/,/g, ''));
            if (!title || !id || url.hostname !== 'www.bigbasket.com' || !prices.length)
                continue;
            const packLabel = heading.textContent?.replace(title, '').trim();
            products.push({ id, title, packLabel, price: prices[0], mrp: prices[1], url: url.href,
                inStock: !/out of stock|notify me|sold out/i.test(cardText) && [...card.querySelectorAll('button')].some(b => /^add$/i.test(b.textContent?.trim() ?? '') && !b.disabled),
                imageUrl: card.querySelector('img')?.src, etaMinutes: +eta[1] });
        }
        if (products.length)
            return { kind: 'products', products };
        if (!chooseArea && /no results|no products found/i.test(text))
            return { kind: 'products', products: [] };
        if (Date.now() >= end)
            return { kind: 'unavailable', message: `BigBasket did not expose quick-delivery prices for “${query}”. Choose a delivery area with minute delivery and try again.` };
        await new Promise(resolve => setTimeout(resolve, 250));
    }
}

readZeptoPage:
"use strict";
async function readZeptoPage(query, waitMs = 12000) {
    const end = Date.now() + waitMs;
    while (true) {
        const text = document.body?.innerText ?? '';
        if (/verify you are human|captcha|access denied|request blocked/i.test(text))
            return { kind: 'blocked', message: 'Zepto needs verification on its own page.' };
        let point;
        try {
            point = JSON.parse(localStorage.getItem('user-position') || '{}').state?.userPosition;
        }
        catch { /* no selected area */ }
        const location = Number.isFinite(point?.latitude) && Number.isFinite(point?.longitude)
            ? { lat: point.latitude, lng: point.longitude } : undefined;
        const cards = [...document.querySelectorAll('a[data-testid="product-card"][href*="/pvid/"]')];
        if (/login to continue searching|please log\s?in/i.test(text) && location)
            return { kind: 'needs_login' };
        if (cards.length && location) {
            const products = cards.slice(0, 80).flatMap((card) => {
                const title = card.querySelector('[data-slot-id="ProductName"]')?.textContent?.trim() || card.querySelector('img')?.alt || '';
                const packLabel = card.querySelector('[data-slot-id="PackSize"]')?.textContent?.trim();
                const priceRoot = card.querySelector('[data-slot-id="EdlpPrice"]') ?? card.querySelector('[data-slot-id$="Price"]') ?? card;
                const prices = [...priceRoot.innerText.matchAll(/₹\s*([\d,]+(?:\.\d+)?)/g)]
                    .map((m) => +m[1].replace(/,/g, ''));
                const id = card.pathname.split('/pvid/')[1]?.split('/')[0];
                if (!id || !title || !prices.length)
                    return [];
                return [{ id, title, packLabel, price: prices[0], mrp: prices[1],
                        inStock: card.querySelector('[data-is-out-of-stock]')?.getAttribute('data-is-out-of-stock') !== 'true' && !/out of stock|notify me|sold out/i.test(card.innerText),
                        imageUrl: card.querySelector('img')?.src, url: new URL(card.getAttribute('href'), locationOrigin()).href }];
            });
            if (products.length)
                return { kind: 'products', location, products };
        }
        if (/select location|your location/i.test(text) && !location && Date.now() > end - waitMs + 1500)
            return { kind: 'needs_location', message: 'Choose a delivery area in Zepto, then search again.' };
        if (location && /no (?:products|results)|couldn.t find|no matches/i.test(text))
            return { kind: 'products', products: [], location };
        if (Date.now() >= end)
            return { kind: location ? 'unavailable' : 'needs_location', message: location ? `Zepto did not finish searching for “${query}”. Try again.` : 'Choose a delivery area in Zepto, then search again.' };
        await new Promise((resolve) => setTimeout(resolve, 250));
    }
    function locationOrigin() { return 'https://www.zepto.com'; }
}

readFlipkartPage:
"use strict";
async function readFlipkartPage(query, pincode, apiUrl) {
    const pageUri = `/hyperlocal/pr?q=${encodeURIComponent(query)}&marketplace=HYPERLOCAL&sid=search.flipkart.com`;
    const response = await fetch(apiUrl, {
        method: 'POST', credentials: 'include', headers: { 'content-type': 'application/json', flipkart_secure: 'true',
            'x-user-agent': navigator.userAgent.includes('FKUA/msite') ? navigator.userAgent : `${navigator.userAgent} FKUA/msite/0.0.4/msite/Mobile` },
        body: JSON.stringify({ pageUri, pageContext: { networkSpeed: 1700 }, requestContext: { type: 'BROWSE_PAGE' }, locationContext: { pincode: +pincode, changed: false } }),
    });
    if (response.status === 401)
        return { kind: 'needs_login' };
    if (response.status === 403 || response.status === 429)
        return { kind: 'blocked', message: `Flipkart Minutes returned HTTP ${response.status}. Open its delivery area screen and try again.` };
    if (!response.ok)
        return { kind: 'unavailable', message: `Flipkart Minutes returned HTTP ${response.status}.` };
    const json = await response.json();
    const result = json.RESPONSE ?? json;
    const redirect = result.pageMeta?.redirectionObject?.url ?? '';
    if (/login|account\/login/.test(redirect))
        return { kind: 'needs_login' };
    if (/hyperlocal-preview|address-map|shippingAddress/i.test(redirect))
        return { kind: 'needs_location', message: 'Choose an exact delivery address in Flipkart Minutes, then search again.' };
    if (redirect)
        return { kind: 'unavailable', message: 'Flipkart did not return a Minutes search. Regular marketplace results were excluded.' };
    const marketplace = result.pageMeta?.marketplace ?? result.pageData?.marketplace;
    if (marketplace && marketplace !== 'HYPERLOCAL')
        return { kind: 'unavailable', message: 'Flipkart returned regular marketplace results; only Minutes is enabled.' };
    const slots = result.slots;
    if (!Array.isArray(slots))
        return { kind: 'unavailable', message: 'Flipkart changed its search response. No prices were guessed.' };
    const products = [];
    const seen = new Set();
    function walk(value) {
        if (!value || typeof value !== 'object')
            return;
        const v = value; // provider's server-driven widget tree
        if (v.pricing?.finalPrice && (v.titles || v.productTitle)) {
            const rawUrl = v.baseUrl || v.smartUrl || '';
            let url;
            try {
                url = new URL(rawUrl, 'https://www.flipkart.com');
            }
            catch {
                return;
            }
            if (url.hostname !== 'www.flipkart.com' || !url.pathname.includes('/p/'))
                return;
            if (url.searchParams.has('marketplace') && url.searchParams.get('marketplace') !== 'HYPERLOCAL')
                return;
            const id = v.id || v.productId || url.searchParams.get('pid') || url.pathname.split('/p/')[1];
            if (!id || seen.has(id))
                return;
            seen.add(id);
            url.searchParams.set('marketplace', 'HYPERLOCAL');
            const price = Number(v.pricing.finalPrice.value);
            const mrp = Number(v.pricing.prices?.find((p) => p.priceType === 'MRP')?.value ?? v.pricing.mrp);
            const title = v.titles?.title || v.titles?.newTitle || v.productTitle;
            const subtitle = v.titles?.subtitle;
            const image = v.media?.images?.[0]?.url || v.images?.[0]?.url;
            products.push({ id: String(id), title, packLabel: typeof subtitle === 'string' && /\d/.test(subtitle) ? subtitle : undefined, price, mrp,
                inStock: !['OUT_OF_STOCK', 'CURRENTLY_UNAVAILABLE', 'NOT_SERVICEABLE'].includes(v.availability?.displayState)
                    && v.productAction?.value?.enabled !== false && v.buyability?.intent !== 'negative',
                imageUrl: typeof image === 'string' ? image.replace('{@width}', '240').replace('{@height}', '240').replace('{@quality}', '80') : undefined, url: url.href });
            return;
        }
        for (const child of Object.values(v))
            if (child && typeof child === 'object')
                walk(child);
    }
    walk(slots);
    if (!products.length && /not.serviceable|not.deliver|not.available.in|coming.soon/i.test(JSON.stringify(result.pageData ?? {}))) {
        return { kind: 'needs_location', message: 'Flipkart Minutes is not serving the selected address. Choose a serviceable delivery area.' };
    }
    return { kind: 'products', products };
}

readAmazonNowPage:
"use strict";
async function readAmazonNowPage(query, pincode) {
    const unavailable = (message = 'Amazon Now is not exposed in this web session. Regular Amazon and Fresh listings were excluded.') => ({ kind: 'unavailable', message });
    const text = document.body?.innerText ?? '';
    if (/enter the characters you see|robot check|captcha/i.test(text))
        return { kind: 'blocked', message: 'Amazon needs verification on its own page.' };
    const selectedPin = (document.querySelector('#glow-ingress-line2')?.textContent ?? '').match(/\b\d{6}\b/)?.[0];
    if (selectedPin && selectedPin !== pincode)
        return { kind: 'needs_location', message: `Choose ${pincode} in Amazon Now before comparing prices.` };
    const entry = [...document.querySelectorAll('a[href]')].find((a) => {
        const label = `${a.getAttribute('aria-label') || ''} ${a.textContent || ''} ${a.querySelector('img')?.alt || ''}`.trim();
        const url = new URL(a.href, 'https://www.amazon.in');
        return url.hostname === 'www.amazon.in' && (/amazon\s*now/i.test(label) || /^now$/i.test(label))
            && /\/alm\/|\/fmc\/|\/now(?:\/|\?|$)/.test(url.href) && url.searchParams.get('almBrandId') !== 'ctnow';
    });
    if (!entry)
        return unavailable();
    const homeResponse = await fetch(entry.href, { credentials: 'include' });
    if (homeResponse.status === 403 || homeResponse.status === 429)
        return { kind: 'blocked', message: `Amazon Now returned HTTP ${homeResponse.status}.` };
    if (!homeResponse.ok)
        return unavailable(`Amazon Now returned HTTP ${homeResponse.status}.`);
    if (/\/ap\/signin/.test(homeResponse.url))
        return { kind: 'needs_login' };
    const home = new DOMParser().parseFromString(await homeResponse.text(), 'text/html');
    const storeUrl = new URL(homeResponse.url);
    const brand = storeUrl.searchParams.get('almBrandId');
    const form = home.querySelector('form[name="site-search"],form[role="search"],#nav-search-bar-form');
    const alias = home.querySelector('#searchDropdownBox')?.value ?? '';
    if (brand === 'ctnow' || /fresh|grocery/i.test(alias))
        return unavailable('Amazon returned Fresh rather than Now. Only quick delivery is enabled.');
    const search = new URL(form?.getAttribute('action') || '/s', 'https://www.amazon.in');
    if (search.hostname !== 'www.amazon.in')
        return unavailable();
    for (const input of form?.querySelectorAll('input[type="hidden"]') ?? []) {
        if (['i', 'almBrandId', 'almStoreId', 'node'].includes(input.name))
            search.searchParams.set(input.name, input.value);
    }
    if (brand)
        search.searchParams.set('almBrandId', brand);
    if (/now/i.test(alias))
        search.searchParams.set('i', alias.replace(/^search-alias=/, ''));
    if (!brand && !/now/i.test(search.searchParams.get('i') ?? ''))
        return unavailable('Amazon Now did not expose a store-specific search. Regular listings were excluded.');
    search.searchParams.set('k', query);
    const response = await fetch(search.href, { credentials: 'include' });
    if (response.status === 403 || response.status === 429)
        return { kind: 'blocked', message: `Amazon Now returned HTTP ${response.status}.` };
    if (!response.ok)
        return unavailable(`Amazon Now returned HTTP ${response.status}.`);
    const doc = new DOMParser().parseFromString(await response.text(), 'text/html');
    if (doc.querySelector('form[name="signIn"]'))
        return { kind: 'needs_login' };
    const header = `${doc.querySelector('#nav-subnav')?.textContent || ''} ${doc.querySelector('h1')?.textContent || ''} ${[...doc.querySelectorAll('header img,#nav-logo img')].map(i => i.alt).join(' ')}`;
    if (!/amazon\s*now|^\s*now\s*$/i.test(header))
        return unavailable('Amazon returned a search without a verified Now store. No marketplace prices were included.');
    const products = [];
    for (const card of doc.querySelectorAll('[data-component-type="s-search-result"][data-asin]')) {
        const title = card.querySelector('h2')?.textContent?.trim() || card.querySelector('img')?.alt;
        const price = Number(card.querySelector('.a-price:not(.a-text-price) .a-offscreen')?.textContent?.replace(/[^\d.]/g, ''));
        const mrp = Number(card.querySelector('.a-price.a-text-price .a-offscreen')?.textContent?.replace(/[^\d.]/g, ''));
        const cardText = card.textContent || '';
        if (!title || !Number.isFinite(price) || price <= 0 || /tomorrow|next.day|\b(?:mon|tues|wednes|thurs|fri|satur|sun)day\b|\b\d+\s*(?:hours?|days?)\b/i.test(cardText))
            continue;
        const id = card.dataset.asin;
        const url = new URL(`/dp/${id}`, 'https://www.amazon.in');
        if (brand)
            url.searchParams.set('almBrandId', brand);
        const eta = cardText.match(/\b(\d+)\s*(?:mins?|minutes?)\b/i);
        products.push({ id, title, price, mrp, url: url.href, imageUrl: card.querySelector('img')?.src,
            inStock: !/currently unavailable|out of stock/i.test(cardText), etaMinutes: eta ? +eta[1] : undefined });
    }
    return { kind: 'products', products };
}
